class Solution {
public:
    int numTeams(vector<int>& rating) {
        int n = rating.size();
        // Coordinate compression
        vector<int> sorted = rating;
        sort(sorted.begin(), sorted.end());
        vector<int> comp(n);
        for (int i = 0; i < n; i++) {
            comp[i] = lower_bound(sorted.begin(), sorted.end(), rating[i]) - sorted.begin() + 1;
        }

        vector<int> bit(n + 2, 0);
        auto update = [&](int i, int delta) {
            for (; i <= n; i += i & (-i)) bit[i] += delta;
        };
        auto query = [&](int i) {
            int s = 0;
            for (; i > 0; i -= i & (-i)) s += bit[i];
            return s;
        };

        vector<int> leftSmaller(n), leftLarger(n), rightSmaller(n), rightLarger(n);

        // Left to right pass
        for (int j = 0; j < n; j++) {
            int c = comp[j];
            leftSmaller[j] = query(c - 1);
            leftLarger[j]  = query(n) - query(c);
            update(c, 1);
        }

        // Reset BIT
        fill(bit.begin(), bit.end(), 0);

        // Right to left pass
        for (int j = n - 1; j >= 0; j--) {
            int c = comp[j];
            rightSmaller[j] = query(c - 1);
            rightLarger[j]  = query(n) - query(c);
            update(c, 1);
        }

        long long ans = 0;
        for (int j = 0; j < n; j++) {
            ans += (long long)leftSmaller[j] * rightLarger[j];
            ans += (long long)leftLarger[j]  * rightSmaller[j];
        }
        return (int)ans;
    }
};
